typeDefs:
typedef struct dwarf_attr_kind {
	ut64 attr_name;
	ut64 attr_form;
	RzBinDwarfAttrKind kind;
	/* This is subideal, as dw_form_data can be anything
	   we could lose information example: encoding signed
	   2 byte int into ut64 and then interpreting it as st64 TODO*/
	union {
		ut64 address;
		RzBinDwarfBlock block;
		ut64 uconstant;
		st64 sconstant;
		ut8 flag;
		ut64 reference;
		struct {
			const char *content;
			ut64 offset;
		} string;
	};
} RzBinDwarfAttrValue;

typedef struct {
	ut64 tag;
	ut64 abbrev_code;
	size_t count;
	size_t capacity;
	ut64 offset; // important for parsing types
	bool has_children; // important for parsing types
	RzBinDwarfAttrValue *attr_values;
}

typedef struct {
	RzBinDwarfCompUnitHdr hdr;
	ut64 offset;
	size_t count;
	size_t capacity;
	RzBinDwarfDie *dies;
}

vulnerableMethods_after:
static int init_die(RzBinDwarfDie *die, ut64 abbr_code, ut64 attr_count) { /* <=== init_die */ 
	if (!die) {
		return -1;
	}
	if (attr_count) {
		die->attr_values = calloc(sizeof(RzBinDwarfAttrValue), attr_count);
		if (!die->attr_values) {
			return -1;
		}
	} else {
		die->attr_values = NULL;
	}
	die->abbrev_code = abbr_code;
	die->capacity = attr_count;
	die->count = 0;
	return 0;
}

static int init_comp_unit(RzBinDwarfCompUnit *cu) { /* <=== init_comp_unit */ 
	if (!cu) {
		return -EINVAL;
	}
	cu->dies = calloc(sizeof(RzBinDwarfDie), COMP_UNIT_CAPACITY);
	if (!cu->dies) {
		return -ENOMEM;
	}
	cu->capacity = COMP_UNIT_CAPACITY;
	cu->count = 0;
	return 0;
}

static int expand_cu(RzBinDwarfCompUnit *cu) { /* <=== expand_cu */ 
	RzBinDwarfDie *tmp;

	if (!cu || cu->capacity == 0 || cu->capacity != cu->count) {
		return -EINVAL;
	}

	tmp = (RzBinDwarfDie *)realloc(cu->dies,
		cu->capacity * 2 * sizeof(RzBinDwarfDie));
	if (!tmp) {
		return -ENOMEM;
	}

	memset((ut8 *)tmp + cu->capacity * sizeof(RzBinDwarfDie),
		0, cu->capacity * sizeof(RzBinDwarfDie));
	cu->dies = tmp;
	cu->capacity *= 2;

	return 0;
}

